theme.css:
/* theme: Storm Signal | A trade war brewing on the horizon while markets waver between fear and recovery — a day of amber warnings and uneasy calm. */
/* mood: tense */
/* layout: hero=split; major-events=banner/grid-2; political-news=numbered/stack; financial-news=stat/grid-3; tech-news=outline/grid-2; entertainment-news=plain/stack; sports=split/masonry; music-releases=plain/stack; stock-analysis=stat/grid-2; outlook=tile/grid-2 */

.diary-page {
  --paper: #241c0a;
  --paper-alt: #2e2510;
  --ink: #f5ecd9;
  --ink-soft: #d8cfbd;
  --muted: #a89d85;
  --accent: #ffb347;
  --accent-ink: #1a1206;
  --rule: #453a24;
  --font-display: var(--ff-archivo-black), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-space-grotesk), sans-serif;
}

.diary-page .diary-hero {
  background: linear-gradient(180deg, #332a12 0%, #241c0a 100%);
  border-bottom: 2px solid var(--accent);
}

.diary-page .diary-hero-inner {
  padding-top: 1.5rem;
  padding-bottom: 2.5rem;
}

.diary-page .diary-kicker {
  color: var(--accent);
  font-family: var(--font-ui);
  letter-spacing: 0.22em;
  font-weight: 700;
}

.diary-page .diary-title {
  font-family: var(--font-display);
  font-size: clamp(2.25rem, 5vw, 4.5rem);
  line-height: 1.05;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  color: var(--ink);
  border-left: 4px solid var(--accent);
  padding-left: 1rem;
}

.diary-page .diary-summary {
  color: var(--ink-soft);
  font-size: clamp(1.1rem, 1.8vw, 1.3rem);
  line-height: 1.6;
  border-left: 2px solid var(--rule);
  padding-left: 1.25rem;
  margin-top: 1.25rem;
}

.diary-page .diary-theme-note {
  color: var(--muted);
  font-family: var(--font-ui);
  font-size: 0.85rem;
  margin-top: 1.5rem;
}

.diary-page .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 0.78rem;
  padding: 0.15rem 0.7rem;
}

.diary-page .diary-crumbs a {
  color: var(--muted);
  font-family: var(--font-ui);
}

.diary-page .diary-crumbs a:hover {
  color: var(--accent);
}

.diary-page .diary-toc {
  background: var(--paper);
  border-bottom-color: var(--rule);
}

.diary-page .diary-toc-label {
  color: var(--muted);
}

.diary-page .diary-toc-link,
.diary-page .diary-toc-top,
.diary-page .diary-toc-bottom {
  color: var(--muted);
  font-family: var(--font-ui);
}

.diary-page .diary-toc-link:hover,
.diary-page .diary-toc-link.is-active {
  color: var(--ink);
}

.diary-page .diary-toc-number {
  color: var(--accent);
}

@media (min-width: 1024px) {
  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
  }
}

@media (max-width: 1023px) {
  .diary-page .diary-toc-list {
    border-left: 0;
  }

  .diary-page .diary-toc-link {
    border-left: 0;
  }
}

.diary-page .diary-section {
  border-top-color: var(--rule);
}

.diary-page .diary-section-number {
  color: var(--accent);
  font-family: var(--font-ui);
  font-weight: 700;
  font-size: 0.9rem;
}

.diary-page .diary-section-title {
  color: var(--ink);
  font-family: var(--font-display);
  letter-spacing: 0.01em;
  text-transform: uppercase;
  font-size: clamp(1.6rem, 3vw, 2.4rem);
}

.diary-page .diary-prose {
  color: var(--ink-soft);
  font-size: 1.1rem;
  line-height: 1.7;
}

.diary-page .diary-prose h3 {
  color: var(--ink);
  font-family: var(--font-ui);
}

.diary-page .diary-prose h4 {
  color: var(--ink);
  font-family: var(--font-display);
}

.diary-page .diary-prose a {
  color: var(--accent);
  font-family: var(--font-ui);
}

.diary-page .diary-prose a:hover {
  color: var(--ink);
}

.diary-page .diary-prose strong {
  color: var(--ink);
}

.diary-page .diary-prose blockquote {
  color: var(--ink);
  border-left-color: var(--accent);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
}

.diary-page .diary-prose ol > li::marker {
  color: var(--accent);
}

.diary-page :is(.diary-spark-label, .diary-spark-value, .diary-spark-change) {
  font-family: var(--font-ui);
}

.diary-page .diary-spark {
  background: var(--paper-alt);
  border-color: var(--rule);
}

.diary-page .diary-spark.is-up .diary-spark-change {
  color: var(--ink);
}

.diary-page .diary-spark.is-down .diary-spark-change {
  color: var(--accent);
}

.diary-page .diary-footer {
  border-top-color: var(--rule);
  color: var(--muted);
  font-family: var(--font-ui);
}

.diary-page .diary-footer a {
  color: var(--ink);
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

/* Major Events: banner cards with a stronger band */
.diary-page [data-card="banner"] .diary-card-inner {
  border-color: var(--rule);
  background: #2a2210;
}

.diary-page [data-card="banner"] .diary-card-title {
  background: var(--accent);
  color: var(--accent-ink);
  font-family: var(--font-display);
  font-size: 1.2rem;
  letter-spacing: 0.02em;
  padding: 1rem 1.25rem;
}

.diary-page [data-card="banner"] .diary-card-body {
  padding: 1.25rem;
}

.diary-page [data-card="banner"] .diary-card-thread {
  margin: 1rem 1.25rem 0;
}

/* Numbered cards (political news) */
.diary-page [data-card="numbered"] .diary-card-inner {
  border-left: 3px solid var(--rule);
  padding-left: 1.25rem;
}

.diary-page [data-card="numbered"] .diary-card-index {
  color: var(--accent);
  font-family: var(--font-display);
  font-size: 3.2rem;
}

/* Stat cards: a bold top border and oversized figures */
.diary-page [data-card="stat"] .diary-card-inner {
  border-top: 4px solid var(--accent);
  padding-top: 0.75rem;
}

.diary-page [data-card="stat"] .diary-card-figure {
  color: var(--accent);
  font-family: var(--font-display);
  font-size: clamp(2.4rem, 10cqi, 3.6rem);
  letter-spacing: 0.01em;
}

/* Outline cards: crackled, angular corners */
.diary-page [data-card="outline"] .diary-card-inner {
  border: 1px solid var(--rule);
  border-radius: 0;
  padding: 1.25rem;
  background: #282110;
}

.diary-page [data-card="outline"] .diary-card-title {
  font-family: var(--font-display);
  color: var(--ink);
  font-size: 1.3rem;
}

/* Split cards for sports */
.diary-page [data-card="split"] .diary-card-inner {
  border-top: 2px solid var(--accent);
  padding-top: 1rem;
}

.diary-page [data-card="split"] .diary-card-title {
  color: var(--ink);
  font-family: var(--font-display);
  font-size: 1.35rem;
}

/* Tile cards for outlook: blocks of amber-tinted darkness */
.diary-page [data-card="tile"] .diary-card-inner {
  background: var(--paper-alt);
  padding: 1.5rem;
  border: 1px solid var(--rule);
}

.diary-page [data-card="tile"] .diary-card-title {
  color: var(--ink);
  font-family: var(--font-display);
}

/* Threads: the continuation label stays legible */
.diary-page .diary-card-thread {
  border-color: var(--accent);
  color: var(--accent);
  font-family: var(--font-ui);
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

/* Lede paragraphs (not used today, but keep consistent if present) */
.diary-page .diary-card-lede {
  border-left-color: var(--accent);
  color: var(--ink);
  font-family: var(--font-display);
  font-size: 1.25rem;
}

/* Card titles shared */
.diary-page .diary-card-title {
  color: var(--ink);
  font-family: var(--font-display);
}

/* Card body shared */
.diary-page .diary-card-body {
  color: var(--ink-soft);
  font-size: 1.05rem;
  line-height: 1.7;
}

/* Adjust stack spacing for sections using stack */
.diary-page .diary-stories--stack > .diary-card--plain + .diary-card--plain {
  border-top-color: var(--rule);
}

/* Make sure focus states are clear */
.diary-page a:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

/* Subtle entrance for cards: one fade+rise, no looping */
.diary-page .diary-card {
  animation: rise-in 400ms ease-out both;
}

@media (prefers-reduced-motion: reduce) {
  .diary-page .diary-card {
    animation: none;
  }
}

@keyframes rise-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Hide scrollbar in rail (stock data not in rail, but keep safe) */
.diary-page .diary-stories--rail {
  scrollbar-width: thin;
  scrollbar-color: var(--rule) transparent;
}

/* Remove base drop-cap override for dark theme (keep it subtle) */
.diary-page .diary-section:first-child .diary-card--plain:first-child .diary-prose > p:first-of-type::first-letter {
  color: var(--accent);
  font-family: var(--font-display);
}
